import unittest
from src.usage_normalizer import normalize_usage

class UsageNormalizerTests(unittest.TestCase):
    def test_openai_cached_prompt_tokens_are_disjoint(self):
        result = normalize_usage({"usage": {"prompt_tokens": 1000, "completion_tokens": 50, "prompt_tokens_details": {"cached_tokens": 900}}}, "openai")
        self.assertEqual(result, {"input_tokens": 100, "output_tokens": 50, "cache_read_tokens": 900, "cache_write_tokens": 0})

    def test_anthropic_cache_reads_are_already_disjoint(self):
        result = normalize_usage({"usage": {"input_tokens": 15, "output_tokens": 7, "cache_read_input_tokens": 3, "cache_creation_input_tokens": 2}}, "anthropic")
        self.assertEqual(result, {"input_tokens": 15, "output_tokens": 7, "cache_read_tokens": 3, "cache_write_tokens": 2})

    def test_unknown_dialect_fails_explicitly(self):
        with self.assertRaises(ValueError):
            normalize_usage({"usage": {}}, "unknown")

if __name__ == "__main__":
    unittest.main()

